import React, { useState } from 'react';
import {
  Box,
  Backdrop,
  SpeedDial as MUISpeedDial,
  SpeedDialAction,
  SpeedDialIcon,
  Slide,
} from '@mui/material';
import {
  ForumRounded as ContactsIcon,
  Telegram as TelegramIcon,
  WhatsApp as WhatsAppIcon,
  PhoneRounded as PhoneIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { TELEGRAM_ID, PHONE_NUMBER } from '../../constants';
import { SpeedDialContent } from './components/speed-dial-content';

const actions = [
  { icon: <TelegramIcon />, code: 'telegram', href: `https://t.me/${TELEGRAM_ID}` },
  { icon: <WhatsAppIcon />, code: 'whatsApp', href: `https://wa.me/${PHONE_NUMBER}` },
  { icon: <PhoneIcon />, code: 'phone', href: `tel:${PHONE_NUMBER}` },
];

const SpeedDial = () => {
  const [open, setOpen] = useState(false);
  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  const { t } = useTranslation();

  return (
    <>
      <Backdrop open={open} sx={{ zIndex: 1000 }} />
      <Box
        sx={{
          zIndex: 1001,
          position: 'sticky',
          bottom: 24,
        }}
      >
        <Slide in direction="up" timeout={{ enter: 1000 }}>
          <MUISpeedDial
            ariaLabel="contacts"
            onClose={handleClose}
            onOpen={handleOpen}
            sx={{
              position: { xs: 'absolute', xl: 'fixed' },
              right: { xs: 18, sm: 24 },
              bottom: { xs: 0, xl: 24 },
              alignItems: 'end',
            }}
            FabProps={{ variant: 'extended' }}
            icon={(
              <SpeedDialContent
                icon={<ContactsIcon />}
                text={t('socials.contactUs')}
                bold
              />
            )}
            transitionDuration={{ enter: 1000 }}
          >
            {actions.map(({ code, href, icon }) => (
              <SpeedDialAction
                key={code}
                FabProps={{
                  variant: 'extended',
                  sx: {
                    px: 2,
                    width: 'fit-content',
                    alignSelf: 'end',
                    textTransform: 'none',
                  },
                }}
                icon={(
                  <SpeedDialIcon
                    icon={(
                      <SpeedDialContent
                        href={href}
                        icon={icon}
                        text={t(`socials.${code}`)}
                      />
                  )}
                  />
              )}
              />
            ))}
          </MUISpeedDial>
        </Slide>
      </Box>
    </>
  );
};

export const MemoizedSpeedDial = React.memo(SpeedDial);
